class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        # Required argument retained; do not consume the live training loader.
        module_modes = [(m, m.training) for m in self.view.model.modules()]
        python_state, numpy_state = snapshot_global_rng_states()
        try:
            with torch.random.fork_rng(devices=active_cuda_devices(self.device)):
                self.view.model.eval()
                with torch.inference_mode():
                    snapshot = immutable_training_history_snapshot(self.view)
                    local_rngs = generators_from_stable_sha256_identifiers(seed=42)
                    diagnostic_loader = independent_loader(snapshot, local_rngs, workers=0)
                    metrics = bounded_margin_probes(diagnostic_loader)
                    for user in fixed_five_user_panel_for_current_dataset(snapshot):
                        original_history = snapshot[user]
                        baseline = left_pad(latest_L(original_history))
                        if empty(baseline):
                            record_skip(user, 'empty_history')
                            continue
                        candidates = ascending_item_ids_excluding(
                            padding=0, observed=original_history, catalog=trained_catalog()
                        )
                        if empty(candidates):
                            record_skip(user, 'empty_candidate_pool')
                            continue
                        original = score_chunked(
                            self.view.predict_score,
                            self.view.log2feats(baseline)[:, -1, :],
                            candidates
                        )
                        for edit, draw, edited_history in preregistered_edits(baseline, local_rngs):
                            edited = left_pad(latest_L(nonpadding(edited_history)))
                            changed = score_chunked(
                                self.view.predict_score,
                                self.view.log2feats(edited)[:, -1, :],
                                candidates
                            )
                            cache_paired_statistics_with_stable_ties(
                                user, edit, draw, candidates, original, changed
                            )
                    metrics.update(aggregate_draws_within_user_then_users())
                    metrics.update(counts_balance_missingness_and_supported_controls())
                    return {'metrics': metrics, 'metric_definitions': explicit_definitions()}
        finally:
            for module, training_flag in module_modes:
                module.training = training_flag
            restore_global_rng_states(python_state, numpy_state)

